"""Customer insight endpoints for the account team."""

from __future__ import annotations

from orders.application.pricing import discount_for
from orders.controllers.http import Response
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository


class CustomerInsightsController:
    def __init__(self, customers: InMemoryCustomerRepository, orders: InMemoryOrderRepository) -> None:
        self._customers = customers
        self._orders = orders

    def handle_order_history(self, customer_id: str) -> Response:
        """Return order history for a customer, newest orders first."""
        customer = self._customers.get(customer_id)
        if customer is None:
            return Response(404, {"error": "customer not found"})

        customer_orders = self._orders.list_for_customer(customer_id)
        tier = customer.tier

        orders_list = []
        for order in reversed(customer_orders):
            subtotal = order.subtotal_cents
            discount = discount_for(subtotal, tier)
            total_cents = subtotal - discount
            orders_list.append({
                "order_id": order.order_id,
                "status": order.status,
                "total_cents": total_cents,
            })

        return Response(200, {
            "customer_id": customer_id,
            "orders": orders_list,
        })

